properties.property:
[
  {
    "text":"Honoring those who died in the ancient Phyrexian Invasion.
Gone but not forgotten.",
    "options":[
      { "name":"Continue" }
]
}
]

[
	{
		"name": "",
		"text": "'Capenna deserves better than the five families. Will you help me bring a better tomorrow?'",
		"options":
			[
				{
					"name": "The five families have fallen.",
                    "text": "'Your actions will bring a new dawn of justice to my people. I thank you.'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
		      {"type": "item", "count": 1, "itemName": "Hero's Heirloom"},
                        {"type": "card", "count": 1, "cardName": "Elspeth Resplendent"},
                        {"type": "card", "count": 1, "cardName": "Elspeth, Knight-Errant"},
                        {"type": "card", "count": 1, "cardName": "Archangel Elspeth"},
                        {"type": "card", "count": 1, "cardName": "Elspeth, Storm Slayer"},
                        {"type": "card", "count": 1, "cardName": "Elspeth Tirel"}              
                      ] } ]
                    ,
					"condition": [{"item": "Brokers Boots"}, {"item": "Cabaretti Kicks"}, {"item": "Obscura Shoes"}, {"item": "Riveteer Greaves"}, {"item": "Maestro Loafers"}],
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "Can you tell me more?",
					"text": "'Long ago, Phyrexians invaded Capenna. They killed almost everyone on the plane. The survivors piled into the last city, named New Capenna. But demons soon took it over, making it a place of crime and fear.'",
					"options": [ { "name": "So what do you need me to do?",
					"text": "'In each biome, one member of the five families has a headquarters. Defeat each crime lord and show me their items as proof of your victory and I'll reward you.'",
					"options": [ { "name": "I'll get to work then." } ]
					 }]
				},
                {
					"name": "Capenna doesn't concern me.",
					"text": "'Very well. I will just have to avenge my people myself.'",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]

[
{
   "text": "A memorial stands ahead, graves stretching out to either side. An angel clad in warrior's armor kneels before the fountain at the memorial's center in silent prayer.",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]
